INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_CHOIR_CIV','The Hollow Choir'),
 ('TXT_KEY_CWC3_CHOIR_SHORT','Hollow Choir'),
 ('TXT_KEY_CWC3_CHOIR_ADJECTIVE','Hollow Choir'),
 ('TXT_KEY_CWC3_CHOIR_LEADER','The First Note'),
 ('TXT_KEY_CWC3_CHOIR_TRAIT','Songs Beneath Stone'),
 ('TXT_KEY_CWC3_CHOIR_TRAIT_HELP','Cities on Hills receive +1 [ICON_PRODUCTION] Production, including captured cities. Cities gain +1 [ICON_PEACE] Faith per adjacent Mountain, up to +2 Faith. Mountain ownership is not required; Faith does not require a Hill city.'),
 ('TXT_KEY_CWC3_CHOIR_CIV_PEDIA','Beneath the mountains, the Hollow Choir preserves ancient memories in translucent violet crystals. Patient voices resonate through silver-veined underground cathedrals, carrying knowledge and culture across the ages.'),
 ('TXT_KEY_CWC3_CHOIR_STRATEGY','Settle Hills beside Mountains for Production and Faith. Acquire Mountain tiles within three tiles of your cities and build Resonance Halls for Culture and Science. Protect your homeland with Chorus Sentinels.'),
 ('TXT_KEY_CWC3_CHOIR_LEADER_PEDIA','The First Note is an ancient sentient crystal suspended in an immense underground cathedral, surrounded by smaller orbiting crystals. Patient and protective, it values knowledge, culture and the enduring harmony of its homeland above unnecessary war.'),
 ('TXT_KEY_CWC3_CHOIR_UNIT','Chorus Sentinel'),
 ('TXT_KEY_CWC3_CHOIR_UNIT_HELP','Replaces the Swordsman. Gains +1 Sight and +20% Combat Strength when defending on Hills. Retains its unique promotion when upgraded.'),
 ('TXT_KEY_CWC3_CHOIR_UNIT_PEDIA','Crystalline warriors listen for the slightest disturbance in the stone. Their watchful ranks defend the mountain approaches to the hidden cathedrals.'),
 ('TXT_KEY_CWC3_CHOIR_UNIT_STRATEGY','Defend Hill positions and use additional Sight to watch approaches. Retains the active Swordsman baseline, resource needs and upgrade path. Its unique promotion persists through upgrades.'),
 ('TXT_KEY_CWC3_CHOIR_PROMOTION','Chorus Sentinel'),
 ('TXT_KEY_CWC3_CHOIR_PROMOTION_HELP','+1 Sight and +20% Combat Strength when defending on Hills. No attack bonus. Persists through upgrades.'),
 ('TXT_KEY_CWC3_CHOIR_HALL','Resonance Hall'),
 ('TXT_KEY_CWC3_CHOIR_HALL_HELP','Replaces the Amphitheater, preserving all its normal effects. Provides +1 additional [ICON_CULTURE] Culture and +1 [ICON_RESEARCH] Science for every 2 owned Mountain tiles within 3 tiles of the city, up to +2 Science. Mountains need not be worked and can count for multiple cities. Conditional Science requires Hollow Choir ownership and this building.'),
 ('TXT_KEY_CWC3_CHOIR_HALL_PEDIA','In vast crystalline concert chambers, the Choir stores its oldest memories as resonating harmonies. Mountain stone carries these voices into an enduring archive of art and discovery.'),
 ('TXT_KEY_CWC3_CHOIR_HALL_STRATEGY','Build for normal Amphitheater effects and +1 Culture. Own two Mountains within radius three for +1 Science, or four for the +2 cap. Shared Mountains can support several Halls.'),
 ('TXT_KEY_CWC3_CHOIR_DUMMY','Hollow Choir Resonance'),
 ('TXT_KEY_CWC3_CHOIR_DUMMY_HELP','Internal terrain yield controller. Cannot be constructed or purchased.'),
 ('TXT_KEY_CWC3_CHOIR_GREETING_1','A new voice... how curious. Come closer, little one. The stone has much to tell you.'),
 ('TXT_KEY_CWC3_CHOIR_WAR_1','Your footsteps disturb the harmony. We shall teach you silence.'),
 ('TXT_KEY_CWC3_CHOIR_DEFEAT_1','The song... does not end... with me...'),
 ('TXT_KEY_CWC3_CHOIR_PEACE_1','Let the echoes of battle fade. There is room for your voice in the silence.'),
 ('TXT_KEY_CWC3_CHOIR_FRIENDLY_1','Your voice returns, familiar and welcome among the stones.'),
 ('TXT_KEY_CWC3_CHOIR_NEUTRAL_1','Speak. The mountains are patient, and we are listening.'),
 ('TXT_KEY_CWC3_CHOIR_HOSTILE_1','Your discord carries far. Choose your next words with care.'),
 ('TXT_KEY_CWC3_CHOIR_ATTACKED_1','You strike the ancient stone. Its answer will endure.'),
 ('TXT_KEY_CWC3_CHOIR_TRADE_1','These notes resolve in harmony. We accept.'),
 ('TXT_KEY_CWC3_CHOIR_FALLBACK_1','We have heard your words. Let the stone remember this moment.'),
 ('TXT_KEY_CWC3_CHOIR_DAWN','Ancient First Note, Voice of the Eternal Mountains, your people await your song.[NEWLINE][NEWLINE]Before the first kingdoms rose, before the first cities were founded, before humanity learned to shape stone, your voice echoed through the darkness beneath the earth.[NEWLINE][NEWLINE]For countless ages, your people remained hidden within the mountains, preserving their memories in the crystalline chambers of their homeland.[NEWLINE][NEWLINE]Empires rose and fell upon the surface.[NEWLINE][NEWLINE]Wars were fought. Cities burned. Civilizations disappeared.[NEWLINE][NEWLINE]Yet the mountains endured.[NEWLINE][NEWLINE]And within them, the songs of your people continued.[NEWLINE][NEWLINE]Now, the Hollow Choir has awakened.[NEWLINE][NEWLINE]Raise your crystalline cities. Gather the voices of your people. Let the mountains themselves become monuments to your civilization.[NEWLINE][NEWLINE]Will your eternal symphony echo throughout the world?'),
 ('TXT_KEY_CWC3_CHOIR_CITY_1','Resonance'),
 ('TXT_KEY_CWC3_CHOIR_CITY_2','Amethyst Vault'),
 ('TXT_KEY_CWC3_CHOIR_CITY_3','Echoing Deep'),
 ('TXT_KEY_CWC3_CHOIR_CITY_4','Still Chord'),
